import { writeFileSync } from "node:fs";
import { getMigrations } from "better-auth/db/migration";
import { loadConfig } from "../config";
import { openDatabase } from "./database";
import { createAuth } from "../auth/auth";
import { createMailer } from "../auth/email";
const config = loadConfig(),
  db = openDatabase(":memory:"),
  auth = createAuth(db, config, createMailer(config));
const migration = await getMigrations(auth.options);
const sql = await migration.compileMigrations();
writeFileSync(
  new URL("./migrations/000_better_auth_generated.sql", import.meta.url),
  "-- Generated by Better Auth 1.7.18; runtime uses the library migration API.\n" +
    sql +
    "\n",
);
await migration.runMigrations();
await (await auth.$context).checkSchema?.();
db.close();
console.log("Đã xuất lược đồ Better Auth.");
